From 1c893c897ee1d026b0fadcca2601f42f9f50267e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 05:09:27 +0100
Subject: [PATCH] paste: make the paste dialogs window-modal

The filename and "File Already Exists" dialogs were application-modal, so
pasting onto the desktop blocked all of plasmashell, panels included,
until they were closed. They now only block the window they belong to.

BUG: 522157
---
 src/widgets/paste.cpp       | 1 +
 src/widgets/pastedialog.cpp | 2 +-
 2 files changed, 2 insertions(+), 1 deletion(-)

diff --git a/src/widgets/paste.cpp b/src/widgets/paste.cpp
index cc355c719..c2ad3b5c0 100644
--- a/src/widgets/paste.cpp
+++ b/src/widgets/paste.cpp
@@ -47,6 +47,7 @@ static QUrl getDestinationUrl(const QUrl &srcUrl, const QUrl &destUrl, QWidget *
     // And now we're using a put job anyway, no destination checking included.
     if (job->exec()) {
         KIO::RenameDialog dlg(widget, i18n("File Already Exists"), srcUrl, destUrl, KIO::RenameDialog_Overwrite);
+        dlg.setWindowModality(Qt::WindowModal);
         KIO::RenameDialog_Result res = static_cast<KIO::RenameDialog_Result>(dlg.exec());

         if (res == KIO::Result_Rename) {
diff --git a/src/widgets/pastedialog.cpp b/src/widgets/pastedialog.cpp
index 9dbc40010..abd651b8d 100644
--- a/src/widgets/pastedialog.cpp
+++ b/src/widgets/pastedialog.cpp
@@ -27,7 +27,7 @@ KIO::PasteDialog::PasteDialog(const QString &title, const QString &label, const
     : QDialog(parent)
 {
     setWindowTitle(title);
-    setModal(true);
+    setWindowModality(Qt::WindowModal);

     QVBoxLayout *topLayout = new QVBoxLayout(this);

